// Discover current X web config: Bookmarks queryId, features, fieldToggles, public web bearer.
// Input: logged-in x.com/home HTML from the previous HTTP Request node (fetched with the X Session credential).
const html = String($input.first().json.data || '');
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0.0.0 Safari/537.36';
const BASE = 'https://abs.twimg.com/responsive-web/client-web/';
const get = async (url) => {
  try { return String(await this.helpers.httpRequest({ method: 'GET', url, headers: { 'user-agent': UA }, json: false })); }
  catch (e) { return ''; }
};
const OP_RE = /queryId:"([^"]+)",operationName:"Bookmarks",operationType:"query",metadata:\{featureSwitches:\[([^\]]*)\],fieldToggles:\[([^\]]*)\]/;
const list = (s) => (s || '').split(',').map(x => x.replace(/"/g, '').trim()).filter(Boolean);

const mainUrl = (html.match(/https:\/\/abs\.twimg\.com\/responsive-web\/client-web\/main\.[0-9a-f]+\.js/) || [])[0];
let bearer = null, queryId = null, featureNames = [], toggleNames = [], source = null;

if (mainUrl) {
  const mainJs = await get(mainUrl);
  bearer = (mainJs.match(/"(AAAAAAAAAAAAAAAAAAAAA[A-Za-z0-9%]+)"/) || [])[1] || null;
  let m = mainJs.match(OP_RE);
  if (m) { queryId = m[1]; featureNames = list(m[2]); toggleNames = list(m[3]); source = 'main.js'; }

  if (!queryId) {
    // Webpack runtime maps (chunk id -> name, chunk id -> hash) are inlined in the HTML.
    const names = {}, hashes = {};
    for (const p of html.matchAll(/(\d+):"([^"]+)"/g)) {
      if (/^[0-9a-f]{16}$/.test(p[2])) hashes[p[1]] = p[2];
      else if (/^(shared~|bundle\.|loader\.|loaders\.|ondemand\.)/.test(p[2])) names[p[1]] = p[2];
    }
    const score = id => { const n = names[id] || ''; return /Bookmark/.test(n) ? 0 : (n.startsWith('shared~') ? 1 : 2); };
    const cands = Object.keys(hashes).filter(id => score(id) < 2)
      .sort((a, b) => score(a) - score(b) || ((names[b] || '').length - (names[a] || '').length))
      .slice(0, 200);
    for (const id of cands) {
      const js = await get(BASE + (names[id] || id) + '.' + hashes[id] + 'a.js');
      m = js.match(OP_RE);
      if (m) { queryId = m[1]; featureNames = list(m[2]); toggleNames = list(m[3]); source = 'chunk ' + (names[id] || id); break; }
    }
  }
}

let features = {};
for (const f of featureNames) {
  const v = html.match(new RegExp('"' + f + '":\\{"value":(true|false)'));
  features[f] = v ? v[1] === 'true' : false;
}

// Fallback: community-maintained mirror of X's internal API params.
if (!queryId || !bearer) {
  try {
    const doc = await this.helpers.httpRequest({ method: 'GET', url: 'https://raw.githubusercontent.com/fa0311/TwitterInternalAPIDocument/refs/heads/develop/docs/json/API.json', json: true });
    const b = doc.graphql && doc.graphql.Bookmarks;
    if (!queryId && b) { queryId = b.queryId; features = b.features || {}; source = 'github fallback'; }
    if (!bearer && doc.header && doc.header.authorization) bearer = String(doc.header.authorization).replace(/^Bearer\s+/i, '');
  } catch (e) {}
}

if (!mainUrl && !queryId) throw new Error('x.com returned a logged-out page. X Session cookies (auth_token/ct0) are likely expired. Refresh the "X Session" credential.');
if (!queryId || !bearer) throw new Error('Could not discover Bookmarks queryId/bearer from x.com JS.');

const fieldToggles = {};
for (const t of toggleNames) fieldToggles[t] = false;

return [{ json: { queryId, bearer, features: JSON.stringify(features), fieldToggles: JSON.stringify(fieldToggles), source, discovered_at: new Date().toISOString(), logged_in: !!mainUrl } }];

const r = $input.first().json;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) {} }
const instr = (body && body.data && body.data.bookmark_timeline_v2 && body.data.bookmark_timeline_v2.timeline && body.data.bookmark_timeline_v2.timeline.instructions) || [];
const add = instr.find(i => i.type === 'TimelineAddEntries') || {};
const entries = add.entries || [];
const d = $('Discover X Config').first().json;
return [{ json: {
  status: r.statusCode,
  entries: entries.length,
  tweets: entries.filter(e => String(e.entryId).startsWith('tweet-')).length,
  cursorBottom: !!entries.find(e => String(e.entryId).startsWith('cursor-bottom')),
  errors: (body && body.errors) || null,
  rawStart: typeof body === 'string' ? body.slice(0, 300) : JSON.stringify(body).slice(0, 300),
  source: d.source, queryId: d.queryId, logged_in: d.logged_in
} }];
